acias por su preferencia."}],"status":"completed","orderKey":"5707e2a38e19604fa2232db611d6189f39db2dc450622a23cb2700bf6284269c","updatedAt":"2026-09-13T21:08:00.000Z"}],"handoffs":[{"phone":"+520001000003","branchSlug":"prol-montejo","estado":"pendiente","motivo":"queja","solicitadaAt":"2026-09-14T14:41:00.000Z","cerradaAt":null},{"phone":"+520001000012","branchSlug":"prol-montejo","estado":"pendiente","motivo":"queja","solicitadaAt":"2026-09-14T14:38:00.000Z","cerradaAt":null},{"phone":"+520001000027","branchSlug":"prol-montejo","estado":"pendiente","motivo":"queja","solicitadaAt":"2026-09-14T14:30:00.000Z","cerradaAt":null}],"callbacks":[{"phone":"0001000003","name":"Natalia Ficticio 0004","branchSlug":"prol-montejo","reason":"escalada:queja","message":"El cliente pidió que una persona lo contacte.","resolved":false,"createdAt":"2026-09-14T14:41:00.000Z"},{"phone":"0001000012","name":"Sofía Ejemplo 0013","branchSlug":"prol-montejo","reason":"escalada:queja","message":"El cliente pidió que una persona lo contacte.","resolved":false,"createdAt":"2026-09-14T14:38:00.000Z"},{"phone":"0001000027","name":"Diego Muestra 0028","branchSlug":"prol-montejo","reason":"escalada:queja","message":"El cliente pidió que una persona lo contacte.","resolved":false,"createdAt":"2026-09-14T14:30:00.000Z"}]}$dv$::jsonb;
  v_org uuid;
begin
  -- 0) solo una organizacion MARCADA como demo; solo telefonos del rango ficticio reservado.
  select o.id into v_org
    from core.organization o join restaurantes.demo_organization d on d.organization_id = o.id
   where o.slug = 'los-taquitos-de-pm-demo';
  if v_org is null then
    raise exception 'demo-volumen: la organizacion "los-taquitos-de-pm-demo" no existe o NO esta marcada como demo (cargue scripts/seed-pm-demo con --demo); no se escribe nada.' using errcode = '42501';
  end if;
  if exists (select 1 from jsonb_to_recordset(v->'customers') as c(phone text) where c.phone !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'orders') as o("customerPhone" text) where o."customerPhone" !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'conversations') as c(phone text) where right(c.phone, 10) !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'callbacks') as c(phone text) where c.phone !~ '^0001[0-9]{6}$') then
    raise exception 'demo-volumen: hay telefonos fuera del rango ficticio reservado 0001xxxxxx; no se escribe nada.' using errcode = '22023';
  end if;

  -- 1) clientes (y su direccion): por (organizacion, telefono)
  insert into restaurantes.customers (organization_id, phone, name, order_count, created_at, updated_at)
    select v_org, c.phone, c.name, 0, c."firstOrderAt", c."firstOrderAt"
    from jsonb_to_recordset(v->'customers') as c(phone text, name text, "firstOrderAt" timestamptz)
    on conflict (organization_id, phone) do nothing;
  insert into restaurantes.customer_addresses (customer_id, label, address, is_default)
    select cu.id, 'Casa', c.address, true
    from jsonb_to_recordset(v->'customers') as c(phone text, address text)
    join restaurantes.customers cu on cu.organization_id = v_org and cu.phone = c.phone
    on conflict (customer_id, address) do nothing;

  -- 2) pedidos: totales y renglones ya calculados por el motor real; deduplicados por clave de idempotencia
  insert into restaurantes.orders (organization_id, property_id, customer_id, customer_name, customer_phone, customer_address, branch, total, status, items, source, notes,
                                   payment_method, idempotency_key, created_at, delivered_at, canal, propina)
    select v_org, bd.property_id, cu.id, o."customerName", o."customerPhone", o.address, o."branchName", o.total, o.status, o.items, o.source, o.notes,
           o."paymentMethod", o."idempotencyKey", o."createdAt", o."deliveredAt", o.canal, o.propina
    from jsonb_to_recordset(v->'orders') as o("idempotencyKey" text, "branchSlug" text, "branchName" text, "customerPhone" text, "customerName" text, address text, items jsonb,
                                             total numeric, status text, source text, "paymentMethod" text, canal text, propina numeric, notes text,
                                             "createdAt" timestamptz, "deliveredAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = o."branchSlug"
    join restaurantes.customers cu on cu.organization_id = v_org and cu.phone = o."customerPhone"
    on conflict (organization_id, idempotency_key) where idempotency_key is not null do nothing;

  -- 3) agregados del cliente a partir de SUS pedidos (coherencia: nunca un contador inventado)
  update restaurantes.customers cu
     set order_count = a.n, last_order_at = a.ultimo, updated_at = greatest(cu.updated_at, a.ultimo)
    from (
      select o.customer_id, (count(*) filter (where o.status <> 'cancelado'))::int as n, max(o.created_at) as ultimo
        from restaurantes.orders o
       where o.organization_id = v_org
         and o.customer_phone in (select x."customerPhone" from jsonb_to_recordset(v->'orders') as x("customerPhone" text))
       group by o.customer_id
    ) a
   where cu.id = a.customer_id;

  -- 4) conversaciones de WhatsApp (una por telefono) ligadas a su pedido
  insert into restaurantes.whatsapp_conversations (organization_id, phone, property_id, messages, status, order_id, created_at, updated_at)
    select v_org, c.phone, bd.property_id, c.messages, c.status, o.id, c."updatedAt", c."updatedAt"
    from jsonb_to_recordset(v->'conversations') as c(phone text, "branchSlug" text, messages jsonb, status text, "orderKey" text, "updatedAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = c."branchSlug"
    left join restaurantes.orders o on o.organization_id = v_org and o.idempotency_key = c."orderKey"
    on conflict (organization_id, phone) do nothing;

  -- 5) tomas de handoff a humano (cerradas y las pendientes recientes): una por conversacion
  insert into restaurantes.conversation_handoff (organization_id, property_id, canal, conversation_id, estado, solicitado_por, motivo, solicitada_at, ultimo_cliente_at, cerrada_at, created_at, updated_at)
    select v_org, bd.property_id, 'whatsapp', wc.id, h.estado, 'agente', h.motivo, h."solicitadaAt", h."solicitadaAt", h."cerradaAt", h."solicitadaAt", coalesce(h."cerradaAt", h."solicitadaAt")
    from jsonb_to_recordset(v->'handoffs') as h(phone text, "branchSlug" text, estado text, motivo text, "solicitadaAt" timestamptz, "cerradaAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = h."branchSlug"
    join restaurantes.whatsapp_conversations wc on wc.organization_id = v_org and wc.phone = h.phone
    where not exists (select 1 from restaurantes.conversation_handoff x where x.canal = 'whatsapp' and x.conversation_id = wc.id);

  -- 6) contactos (callbacks) registrados por el agente al escalar
  insert into restaurantes.callback_requests (organization_id, property_id, customer_name, customer_phone, reason, message, source, resolved, created_at)
    select v_org, bd.property_id, c.name, c.phone, c.reason, c.message, 'whatsapp', c.resolved, c."createdAt"
    from jsonb_to_recordset(v->'callbacks') as c(phone text, name text, "branchSlug" text, reason text, message text, resolved boolean, "createdAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = c."branchSlug"
    where not exists (select 1 from restaurantes.callback_requests x where x.organization_id = v_org and x.customer_phone = c.phone and x.created_at = c."createdAt");
end
$seed_fn$;
create or replace function public.seed_volumen_no_demo() returns void language plpgsql as $seed_fn$
declare
  v jsonb := $dv${"customers":[{"phone":"0001000000","name":"Luis Ejemplo 0001","address":"Calle 42 #153 x 89 y 30, Col. Emiliano Zapata Norte, Mérida","firstOrderAt":"2026-09-04T18:35:00.000Z"}],"orders":[{"idempotencyKey":"d6784d3f9196360c8124400a36462c20a5aa5bebf229e84a1358cd0c78a2ba90","branchSlug":"prol-montejo","branchName":"Prolongación Montejo","customerPhone":"0001000000","customerName":"Luis Ejemplo 0001","address":"Calle 42 #153 x 89 y 30, Col. Emiliano Zapata Norte, Mérida","items":[{"id":"6bc45cc1-9263-4ab6-879c-0dcd765c36ba","name":"Nachos de Chuleta (1/2 orden)","price":249,"quantity":1},{"id":"66101f80-f68e-4702-83da-1b6b24ae0b1d","name":"Papa Chuleta","price":276,"quantity":2},{"id":"aa75bedf-f8f2-44b7-801c-ac265aa802f2","name":"Queso Napolitano","price":109,"quantity":1}],"total":910,"status":"problema","source":"whatsapp","paymentMethod":"efectivo","canal":"domicilio","propina":null,"notes":"Complementos incluidos: salsa roja, salsa verde, salsa mexicana, salsa guacamolera, limones, crema de ajo, cebolla con cilantro, salsa de piña, salsa habanero (soasada o picada con limón).\nCanal: domicilio.","createdAt":"2026-09-04T18:35:00.000Z","deliveredAt":null}],"conversations":[],"handoffs":[],"callbacks":[]}$dv$::jsonb;
  v_org uuid;
begin
  -- 0) solo una organizacion MARCADA como demo; solo telefonos del rango ficticio reservado.
  select o.id into v_org
    from core.organization o join restaurantes.demo_organization d on d.organization_id = o.id
   where o.slug = 'otra-taqueria';
  if v_org is null then
    raise exception 'demo-volumen: la organizacion "otra-taqueria" no existe o NO esta marcada como demo (cargue scripts/seed-pm-demo con --demo); no se escribe nada.' using errcode = '42501';
  end if;
  if exists (select 1 from jsonb_to_recordset(v->'customers') as c(phone text) where c.phone !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'orders') as o("customerPhone" text) where o."customerPhone" !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'conversations') as c(phone text) where right(c.phone, 10) !~ '^0001[0-9]{6}$')
     or exists (select 1 from jsonb_to_recordset(v->'callbacks') as c(phone text) where c.phone !~ '^0001[0-9]{6}$') then
    raise exception 'demo-volumen: hay telefonos fuera del rango ficticio reservado 0001xxxxxx; no se escribe nada.' using errcode = '22023';
  end if;

  -- 1) clientes (y su direccion): por (organizacion, telefono)
  insert into restaurantes.customers (organization_id, phone, name, order_count, created_at, updated_at)
    select v_org, c.phone, c.name, 0, c."firstOrderAt", c."firstOrderAt"
    from jsonb_to_recordset(v->'customers') as c(phone text, name text, "firstOrderAt" timestamptz)
    on conflict (organization_id, phone) do nothing;
  insert into restaurantes.customer_addresses (customer_id, label, address, is_default)
    select cu.id, 'Casa', c.address, true
    from jsonb_to_recordset(v->'customers') as c(phone text, address text)
    join restaurantes.customers cu on cu.organization_id = v_org and cu.phone = c.phone
    on conflict (customer_id, address) do nothing;

  -- 2) pedidos: totales y renglones ya calculados por el motor real; deduplicados por clave de idempotencia
  insert into restaurantes.orders (organization_id, property_id, customer_id, customer_name, customer_phone, customer_address, branch, total, status, items, source, notes,
                                   payment_method, idempotency_key, created_at, delivered_at, canal, propina)
    select v_org, bd.property_id, cu.id, o."customerName", o."customerPhone", o.address, o."branchName", o.total, o.status, o.items, o.source, o.notes,
           o."paymentMethod", o."idempotencyKey", o."createdAt", o."deliveredAt", o.canal, o.propina
    from jsonb_to_recordset(v->'orders') as o("idempotencyKey" text, "branchSlug" text, "branchName" text, "customerPhone" text, "customerName" text, address text, items jsonb,
                                             total numeric, status text, source text, "paymentMethod" text, canal text, propina numeric, notes text,
                                             "createdAt" timestamptz, "deliveredAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = o."branchSlug"
    join restaurantes.customers cu on cu.organization_id = v_org and cu.phone = o."customerPhone"
    on conflict (organization_id, idempotency_key) where idempotency_key is not null do nothing;

  -- 3) agregados del cliente a partir de SUS pedidos (coherencia: nunca un contador inventado)
  update restaurantes.customers cu
     set order_count = a.n, last_order_at = a.ultimo, updated_at = greatest(cu.updated_at, a.ultimo)
    from (
      select o.customer_id, (count(*) filter (where o.status <> 'cancelado'))::int as n, max(o.created_at) as ultimo
        from restaurantes.orders o
       where o.organization_id = v_org
         and o.customer_phone in (select x."customerPhone" from jsonb_to_recordset(v->'orders') as x("customerPhone" text))
       group by o.customer_id
    ) a
   where cu.id = a.customer_id;

  -- 4) conversaciones de WhatsApp (una por telefono) ligadas a su pedido
  insert into restaurantes.whatsapp_conversations (organization_id, phone, property_id, messages, status, order_id, created_at, updated_at)
    select v_org, c.phone, bd.property_id, c.messages, c.status, o.id, c."updatedAt", c."updatedAt"
    from jsonb_to_recordset(v->'conversations') as c(phone text, "branchSlug" text, messages jsonb, status text, "orderKey" text, "updatedAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = c."branchSlug"
    left join restaurantes.orders o on o.organization_id = v_org and o.idempotency_key = c."orderKey"
    on conflict (organization_id, phone) do nothing;

  -- 5) tomas de handoff a humano (cerradas y las pendientes recientes): una por conversacion
  insert into restaurantes.conversation_handoff (organization_id, property_id, canal, conversation_id, estado, solicitado_por, motivo, solicitada_at, ultimo_cliente_at, cerrada_at, created_at, updated_at)
    select v_org, bd.property_id, 'whatsapp', wc.id, h.estado, 'agente', h.motivo, h."solicitadaAt", h."solicitadaAt", h."cerradaAt", h."solicitadaAt", coalesce(h."cerradaAt", h."solicitadaAt")
    from jsonb_to_recordset(v->'handoffs') as h(phone text, "branchSlug" text, estado text, motivo text, "solicitadaAt" timestamptz, "cerradaAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = h."branchSlug"
    join restaurantes.whatsapp_conversations wc on wc.organization_id = v_org and wc.phone = h.phone
    where not exists (select 1 from restaurantes.conversation_handoff x where x.canal = 'whatsapp' and x.conversation_id = wc.id);

  -- 6) contactos (callbacks) registrados por el agente al escalar
  insert into restaurantes.callback_requests (organization_id, property_id, customer_name, customer_phone, reason, message, source, resolved, created_at)
    select v_org, bd.property_id, c.name, c.phone, c.reason, c.message, 'whatsapp', c.resolved, c."createdAt"
    from jsonb_to_recordset(v->'callbacks') as c(phone text, name text, "branchSlug" text, reason text, message text, resolved boolean, "createdAt" timestamptz)
    join restaurantes.branch_detail bd on bd.organization_id = v_org and bd.slug = c."branchSlug"
    where not exists (select 1 from restaurantes.callback_requests x where x.organization_id = v_org and x.customer_phone = c.phone and x.created_at = c."createdAt");
end
$seed_fn$;
create or replace function public.seed_volumen_telefono_real() returns void language plpgsql as $seed_fn$
declare
  v jsonb := $dv${"customers":[{"phone":"0001000000","name":"Luis Ejemplo 0001","address":"Calle 42 #153 x 89 y 30, Col. Emiliano Zapata Norte, Mérida","firstOrderAt":"2026-09-04T18:35:00.000Z"}],"orders":[{"idempotencyKey":"d6784d3f9196360c8124400a36462c20a5aa5bebf229e84a1358cd0c78a2ba90","branchSlug":"prol-montejo","branchName":"Prolongación Montejo","customerPhone":"9991234567","customerName":"Luis Ejemplo 0001","address":"Calle 42 #153 x 89 y 30, Col. Emiliano Zapata Norte, Mérida","items":[{"id":"6bc45cc1-9263-4ab6-879c-0dcd765c36ba","name":"Nachos de Chuleta (1/2 orden)","price":249,"quantity":1},{"id":"66101f80-f68e-4702-83da-1b6b24ae0b1d","name":"Papa Chuleta","price":276,"quantity":2},{"id":"aa75bedf-f8f2-44b7-801c-ac265aa802f2","name":"Queso Napolitano","price":109,"quantity":1}],"total":910,"status":"problema","source":"whatsapp","paymentMethod":"efectivo","canal":"domicilio","propina":null,"notes":"Complementos incluidos: salsa roja, salsa verde, salsa mexicana, salsa guacamolera, limones, crema de ajo, cebolla con cilantro, salsa de piña, salsa habanero (soasada o picada con limón).\nCanal: domicilio.","createdAt":"2026-09-04T18:35:00.000Z","deliveredAt":null}],"conversations":[],"handoffs":[],"callbacks":[]}$dv$::jsonb;
